// 发帖：普通用户推到活跃粉丝收件箱；大 V 只写发件箱
public void publish(long authorId, long postId, long ts) {
    redis.opsForZSet().add("outbox:" + authorId, String.valueOf(postId), ts);
    if (followerCount(authorId) < BIG_V_THRESHOLD) {
        mq.send("feed-fanout", new Fanout(authorId, postId, ts));   // 异步推送
    }
}

// 消费者：分批写活跃粉丝收件箱，只保留最近 1000 条
void onFanout(Fanout f) {
    for (List<Long> batch : activeFollowersInBatches(f.authorId(), 500)) {
        redis.executePipelined((RedisCallback<Object>) c -> {
            for (Long uid : batch) {
                byte[] k = ("inbox:" + uid).getBytes();
                c.zAdd(k, f.ts(), String.valueOf(f.postId()).getBytes());
                c.zRemRange(k, 0, -1001);
            }
            return null;
        });
    }
}

// 读 Feed：收件箱 + 关注的大 V 发件箱，按时间归并，游标分页
List<Long> feed(long uid, long maxTs, int size) {
    Set<TypedTuple<String>> merged = new TreeSet<>(byScoreDesc);
    merged.addAll(redis.opsForZSet().reverseRangeByScoreWithScores("inbox:" + uid, 0, maxTs - 1, 0, size));
    for (long bigV : followedBigVs(uid))
        merged.addAll(redis.opsForZSet().reverseRangeByScoreWithScores("outbox:" + bigV, 0, maxTs - 1, 0, size));
    return merged.stream().limit(size).map(t -> Long.valueOf(t.getValue())).toList();
}
